@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
.mfp.mfp-agf.mfp-native-generated {--agf-primary:#E91E8C;--agf-accent:#29B6F6;--agf-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--agf-text:var(--mf-page-text,var(--mf-preset-text,#1A1A2E));--agf-muted:var(--mf-page-muted,var(--mf-preset-muted,#6B7280));--agf-border:var(--mf-page-border,var(--mf-preset-border,#E5E7EB));--agf-on-primary:var(--mf-preset-on-primary,#FFFFFF);--agf-deco:#29B6F6;--agf-page:#F8F9FE;--agf-fill:#F8F9FE;--agf-fill-strong:color-mix(in srgb, var(--agf-text) 9%, var(--agf-surface));--agf-soft:color-mix(in srgb, var(--agf-primary) 12%, var(--agf-surface));--agf-hairline:color-mix(in srgb, var(--agf-text) 12%, var(--agf-surface));}.mfp.mfp-agf.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-agf.mfp-native-generated {--agf-primary:var(--mf-page-primary,var(--mf-preset-primary,#E91E8C));--agf-accent:var(--mf-page-accent,var(--mf-preset-accent,#29B6F6));--agf-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--agf-text:var(--mf-page-text,var(--mf-preset-text,#1A1A2E));--agf-border:var(--mf-page-border,var(--mf-preset-border,#E5E7EB));--agf-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FFFFFF));--agf-page:var(--mf-preset-bg,#F8F9FE);}@container (max-width:520px){.mfp.mfp-agf.mfp-native-generated [class*="-grid"],.mfp.mfp-agf.mfp-native-generated [class*="-meta"],.mfp.mfp-agf.mfp-native-generated [class*="-scores"],.mfp.mfp-agf.mfp-native-generated [class*="-charts"],.mfp.mfp-agf.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-agf.mfp-native-generated [class*="-body"],.mfp.mfp-agf.mfp-native-generated [class*="-split"],.mfp.mfp-agf.mfp-native-generated [class*="-foot"],.mfp.mfp-agf.mfp-native-generated [class*="-head"],.mfp.mfp-agf.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-agf.mfp-native-generated [class*="-aside"],.mfp.mfp-agf.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-agf.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-agf.mfp-native-generated {overflow-wrap:break-word}
.mfp.mfp-agf.mfp-native-generated {container-type:inline-size;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--agf-text)}
.mfp.mfp-agf.mfp-native-generated .agf-page{background:var(--agf-page)}

/* hero ------------------------------------------------------------------- */
.mfp.mfp-agf.mfp-native-generated .agf-hero{position:relative;overflow:hidden;min-height:320px;
  background-image:url('/DesktopModules/MegaForm/Assets/img/agency-flyer-euroyouth-application/agency-flyer-hero.png'),url('/Modules/MegaForm/img/agency-flyer-euroyouth-application/agency-flyer-hero.png');
  background-size:cover;background-position:50% 50%}
.mfp.mfp-agf.mfp-native-generated img.agf-content-image{position:absolute!important;inset:0!important;display:block!important;
  width:100%!important;height:100%!important;object-fit:cover!important;object-position:50% 50%!important;
  border:0!important;border-radius:0!important;pointer-events:none!important}
.mfp.mfp-agf.mfp-native-generated .agf-hero-wash{position:absolute;inset:0;
  background:linear-gradient(105deg,rgba(233,30,140,.93) 0%,rgba(233,30,140,.6) 35%,transparent 70%)}
.mfp.mfp-agf.mfp-native-generated .agf-hero-strip{position:absolute;left:0;right:0;bottom:0;height:6px;background:var(--agf-accent)}
/* max-w-5xl WITHOUT mx-auto: the headline hugs the left edge in the mock. */
.mfp.mfp-agf.mfp-native-generated .agf-hero-in{position:relative;max-width:1024px;padding:40px 32px}
@container (min-width:768px){.mfp.mfp-agf.mfp-native-generated .agf-hero-in{padding:56px}}
.mfp.mfp-agf.mfp-native-generated .agf-logo{display:flex;align-items:center;gap:8px;margin-bottom:32px}
.mfp.mfp-agf.mfp-native-generated .agf-logo-mark{display:flex;align-items:center;justify-content:center;width:32px;height:32px;
  border-radius:999px;background:#fff;color:var(--agf-primary);font-size:16px;line-height:16px}
.mfp.mfp-agf.mfp-native-generated .agf-logo-t{display:flex;flex-direction:column;font-size:10px;line-height:1.25;font-weight:900;
  letter-spacing:.25em;text-transform:uppercase;color:#fff}
.mfp.mfp-agf.mfp-native-generated .agf-logo-b{color:#E1F5FE}
.mfp.mfp-agf.mfp-native-generated h1.agf-h1{margin:0!important;font-style:italic!important;font-weight:900!important;
  line-height:.9!important;letter-spacing:-1.0667px!important;color:#fff!important}
.mfp.mfp-agf.mfp-native-generated .agf-h1-a,.mfp.mfp-agf.mfp-native-generated .agf-h1-b,.mfp.mfp-agf.mfp-native-generated .agf-h1-c{display:block;font-size:48px;line-height:.9}
@container (min-width:768px){.mfp.mfp-agf.mfp-native-generated .agf-h1-a,.mfp.mfp-agf.mfp-native-generated .agf-h1-b,.mfp.mfp-agf.mfp-native-generated .agf-h1-c{font-size:72px}}
.mfp.mfp-agf.mfp-native-generated .agf-h1-b{color:var(--agf-accent)}

/* content column --------------------------------------------------------- */
.mfp.mfp-agf.mfp-native-generated .agf-main{max-width:1024px;margin:0 auto;padding:32px 24px}
@container (min-width:768px){.mfp.mfp-agf.mfp-native-generated .agf-main{padding:32px 56px}}
.mfp.mfp-agf.mfp-native-generated .agf-svc{margin-bottom:32px;padding:24px;border-radius:16px;background:#fff}
.mfp.mfp-agf.mfp-native-generated .agf-svc-h{margin:0 0 16px;font-size:12px;line-height:16px;font-weight:900;letter-spacing:.1em;
  text-transform:uppercase;color:#6B7280}
.mfp.mfp-agf.mfp-native-generated .agf-svc-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}
.mfp.mfp-agf.mfp-native-generated .agf-svc-g{display:flex;flex-direction:column;gap:4px}
.mfp.mfp-agf.mfp-native-generated .agf-svc-r{display:flex;align-items:center;gap:6px}
.mfp.mfp-agf.mfp-native-generated .agf-dot{width:6px;height:6px;border-radius:999px;flex:0 0 6px}
.mfp.mfp-agf.mfp-native-generated .agf-dot-0{background:var(--agf-primary)}
.mfp.mfp-agf.mfp-native-generated .agf-dot-1{background:var(--agf-accent)}
.mfp.mfp-agf.mfp-native-generated .agf-dot-2{background:#10B981}
.mfp.mfp-agf.mfp-native-generated .agf-svc-t{font-size:11px;line-height:16px;font-weight:500;color:var(--agf-text)}
.mfp.mfp-agf.mfp-native-generated .agf-prog{margin-bottom:32px}
.mfp.mfp-agf.mfp-native-generated .agf-card{margin-bottom:24px;padding:24px;border-radius:16px;background:#fff}

/* captioned hairline rules ---------------------------------------------- */
.mfp.mfp-agf.mfp-native-generated .agf-rule{display:flex;align-items:center;gap:8px;margin-bottom:20px}
.mfp.mfp-agf.mfp-native-generated .agf-hair{flex:1 1 0;height:1px;display:block}
.mfp.mfp-agf.mfp-native-generated .agf-rule-t{padding:0 12px;font-size:11px;line-height:16px;font-weight:900;letter-spacing:.1em;
  text-transform:uppercase}
.mfp.mfp-agf.mfp-native-generated .agf-rule-pink .agf-hair{background:var(--agf-primary)}
.mfp.mfp-agf.mfp-native-generated .agf-rule-pink .agf-rule-t{color:var(--agf-primary)}
.mfp.mfp-agf.mfp-native-generated .agf-rule-blue .agf-hair{background:var(--agf-accent)}
.mfp.mfp-agf.mfp-native-generated .agf-rule-blue .agf-rule-t{color:var(--agf-accent)}
.mfp.mfp-agf.mfp-native-generated .agf-rule-green{margin-bottom:16px}
.mfp.mfp-agf.mfp-native-generated .agf-rule-green .agf-hair{background:#10B981}
.mfp.mfp-agf.mfp-native-generated .agf-rule-green .agf-rule-t{color:#10B981}
.mfp.mfp-agf.mfp-native-generated .agf-rule-grey{margin-bottom:16px}
.mfp.mfp-agf.mfp-native-generated .agf-rule-grey .agf-hair{background:var(--agf-border)}
.mfp.mfp-agf.mfp-native-generated .agf-rule-grey .agf-rule-t{color:#6B7280}

.mfp.mfp-agf.mfp-native-generated .agf-grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px}
.mfp.mfp-agf.mfp-native-generated .agf-field{display:block;margin:0}
.mfp.mfp-agf.mfp-native-generated .agf-label{display:block;margin:0 0 6px;font-size:11px;line-height:16px;font-weight:700;
  letter-spacing:.05em;text-transform:uppercase;color:#6B7280}
.mfp.mfp-agf.mfp-native-generated .agf-chips{margin-bottom:24px}
.mfp.mfp-agf.mfp-native-generated .agf-ta{line-height:0}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-agf.mfp-native-generated label,.mfp.mfp-agf.mfp-native-generated span,.mfp.mfp-agf.mfp-native-generated p,.mfp.mfp-agf.mfp-native-generated div,.mfp.mfp-agf.mfp-native-generated ul,.mfp.mfp-agf.mfp-native-generated li,.mfp.mfp-agf.mfp-native-generated h1,.mfp.mfp-agf.mfp-native-generated h2,.mfp.mfp-agf.mfp-native-generated h3,.mfp.mfp-agf.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-agf.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-agf.mfp-native-generated .mf-section-break,.mfp.mfp-agf.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-agf.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-agf.mfp-native-generated .mf-form-title,.mfp.mfp-agf.mfp-native-generated .mf-form-description,.mfp.mfp-agf.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-agf.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-agf.mfp-native-generated .mf-input[class],.mfp.mfp-agf.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--agf-border)!important;border-radius:8px!important;background:var(--agf-surface)!important;
  padding:10px 16px!important;min-height:0!important;height:auto!important;
  color:var(--agf-text)!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:400!important;box-shadow:none!important}
.mfp.mfp-agf.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-agf.mfp-native-generated .mf-select[class]:focus{border-color:var(--agf-primary)!important;
  box-shadow:none!important;outline:none!important}
.mfp.mfp-agf.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-agf.mfp-native-generated .mf-textarea[class]::placeholder{color:#6B7280!important;opacity:1}
.mfp.mfp-agf.mfp-native-generated .mf-select[class]:invalid,
.mfp.mfp-agf.mfp-native-generated .mf-select[class]:has(option[value=""]:checked){color:#6B7280!important}

.mfp.mfp-agf.mfp-native-generated .mf-input[class],.mfp.mfp-agf.mfp-native-generated .mf-select[class]{border-width:2px!important}
.mfp.mfp-agf.mfp-native-generated .mf-textarea[class]{width:100%!important;box-sizing:border-box!important;
  border:2px solid var(--agf-border)!important;border-radius:8px!important;background:transparent!important;
  padding:12px!important;min-height:88px!important;height:88px!important;resize:none!important;
  margin-bottom:16px!important;color:var(--agf-text)!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;box-shadow:none!important}

/* programme cards -------------------------------------------------------- */
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards{display:grid!important;grid-template-columns:1fr 1fr 1fr!important;
  gap:16px!important}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-ui{display:flex;flex-direction:column;align-items:stretch;
  gap:0;width:100%;box-sizing:border-box;padding:16px;border:2px solid var(--agf-border);border-radius:12px;
  background:#fff;cursor:pointer;transition:all .15s ease}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-icon{display:block!important;width:100%!important;
  height:20px!important;flex:0 0 20px!important;margin:0 0 8px!important;padding:0!important;
  border:0!important;border-radius:0!important;background:transparent!important;
  text-align:left!important;font-size:20px!important;line-height:20px!important;
  font-weight:400!important;color:#6B7280!important}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-label{font-size:13px;line-height:1.25;font-weight:700;
  color:var(--agf-text)}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-desc{display:block;width:100%;margin-top:2px;font-size:11px;
  line-height:16px;font-weight:400;color:#6B7280}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards input:checked+.mf-option-ui{border-color:var(--agf-primary);background:#FCE4F3}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards .mf-option-item.is-selected .mf-option-icon,
.mfp.mfp-agf.mfp-native-generated .mf-option-group--cards input:checked+.mf-option-ui .mf-option-icon{color:var(--agf-primary)!important}

/* interest chips: rounded-lg, NOT pills --------------------------------- */
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips{display:flex;flex-wrap:wrap;gap:8px}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips .mf-option-ui{display:block;gap:0;padding:6px 12px;
  border:2px solid var(--agf-border);border-radius:8px;background:transparent;color:#6B7280;font-size:12px;
  line-height:16px;font-weight:700;text-align:center;cursor:pointer;transition:all .15s ease}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips .mf-option-label{font-size:12px;line-height:16px;font-weight:700;
  color:inherit}
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-agf.mfp-native-generated .mf-option-group--chips input:checked+.mf-option-ui{background:var(--agf-primary);border-color:var(--agf-primary);
  color:#fff}

/* consent, CTA, development strip, back link ---------------------------- */
.mfp.mfp-agf.mfp-native-generated .agf-consent{display:flex;flex-direction:column;gap:12px;margin-bottom:24px}
.mfp.mfp-agf.mfp-native-generated .agf-consent .mf-option-group--list{display:flex;flex-direction:column;gap:12px}
.mfp.mfp-agf.mfp-native-generated .agf-consent .mf-option-item{display:flex;align-items:flex-start;gap:12px}
.mfp.mfp-agf.mfp-native-generated .agf-consent .mf-option-ui{display:block;padding:0;border:0;background:transparent}
.mfp.mfp-agf.mfp-native-generated .agf-consent .mf-option-label{font-size:14px;line-height:20px;font-weight:400;color:#6B7280}
.mfp.mfp-agf.mfp-native-generated .agf-consent input[type="checkbox"]{width:20px!important;height:20px!important;
  flex:0 0 20px!important;margin:2px 0 0!important;border:2px solid var(--agf-border)!important;
  border-radius:6px!important}
.mfp.mfp-agf.mfp-native-generated button.agf-submit[type="submit"]{display:block;width:100%!important;padding:16px 0!important;
  border:0!important;border-radius:12px!important;
  background:linear-gradient(90deg,var(--agf-primary) 0%,var(--agf-accent) 100%)!important;color:#fff!important;
  font-family:inherit!important;font-size:14px!important;line-height:20px!important;
  font-weight:900!important;letter-spacing:.1em!important;text-transform:uppercase!important;
  cursor:pointer!important;box-shadow:none!important}
/* The mock DOES grey its CTA until the form is valid — measured var(--agf-border). */
.mfp.mfp-agf.mfp-native-generated button.agf-submit.mf-nav-blocked,.mfp.mfp-agf.mfp-native-generated button.agf-submit[disabled]{opacity:1;
  background:var(--agf-border)!important;cursor:not-allowed!important;filter:none!important}
.mfp.mfp-agf.mfp-native-generated .agf-dev{border-radius:16px;overflow:hidden}
.mfp.mfp-agf.mfp-native-generated .agf-dev-in{display:flex;align-items:flex-start;gap:16px;padding:20px;background:var(--agf-text)}
.mfp.mfp-agf.mfp-native-generated .agf-dev-tile{display:flex;align-items:center;justify-content:center;flex:0 0 48px;width:48px;
  height:48px;border:2px solid var(--agf-accent);border-radius:12px;color:var(--agf-accent);font-size:24px;
  line-height:24px}
.mfp.mfp-agf.mfp-native-generated .agf-dev-text{display:flex;flex-direction:column}
.mfp.mfp-agf.mfp-native-generated .agf-dev-h{margin-bottom:4px;font-size:14px;line-height:20px;font-weight:900;letter-spacing:.05em;
  text-transform:uppercase;color:#fff}
.mfp.mfp-agf.mfp-native-generated .agf-dev-b{font-size:12px;line-height:1.625;font-weight:400;color:#9CA3AF}
.mfp.mfp-agf.mfp-native-generated .agf-back{margin-top:20px;text-align:center}
.mfp.mfp-agf.mfp-native-generated .agf-back-link{display:inline-flex;align-items:center;gap:8px;font-size:14px;line-height:20px;
  font-weight:500;color:#6B7280}
.mfp.mfp-agf.mfp-native-generated .agf-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-agf.mfp-native-generated .agf-shell,.mfp.mfp-agf.mfp-native-generated .agf-wrap{max-width:none!important;margin:0!important}.mfp.mfp-agf.mfp-native-generated .agf-grid,.mfp.mfp-agf.mfp-native-generated .agf-main,.mfp.mfp-agf.mfp-native-generated .agf-hero-in,.mfp.mfp-agf.mfp-native-generated .agf-card{max-width:none!important;margin-left:0!important;margin-right:0!important}.mfp.mfp-agf.mfp-native-generated .agf-page{border:1px solid var(--agf-border)!important;border-radius:12px!important;overflow:hidden;background:var(--agf-page)!important}.mf-form-wrapper.mf-has-date-popover .mfp.mfp-agf.mfp-native-generated .agf-page{overflow:visible!important}
